       const ytLink = (vid, sec) => `https://www.youtube.com/watch?v=${vid}&t=${Math.floor(sec || 0)}s`;
       // Eingebetteter Player: YouTube über nocookie-Embed mit Startsekunde; Mediathek/sonst direkt.
       const ytEmbed = (vid, sec) => `https://www.youtube-nocookie.com/embed/${vid}?start=${Math.floor(sec || 0)}&autoplay=1&rel=0`;
+      // Video der ganzen Sitzung (YouTube einbettbar; Mediathek öffnet im Tab) — für Meta-Panel + FAB.
+      function sessionVideo(data) {
+        const m = (data && data.metadata) || {}, src = srcInfo(data), e = entryFor(current);
+        if (src && src.video_id) return { embed: ytEmbed(src.video_id, 0), orig: ytLink(src.video_id, 0),
+          label: "▶ Video der Sitzung (YouTube)", title: (m.title || "Sitzung") + " — YouTube" };
+        if (e && e.amtlich && e.amtlich.mediathek) return { embed: e.amtlich.mediathek, orig: e.amtlich.mediathek,
+          label: "▶ Video der Sitzung (Mediathek)", title: (m.title || "Sitzung") + " — Mediathek" };
+        return null;
+      }
+      // Floating Action Button: zeigt/versteckt sich je nach Sitzung + Ansicht; nutzt den playVideo-Pfad.
+      function updateFab() {
+        const f = $("fab"); if (!f) return;
+        const v = !dashOn ? sessionVideo(curData) : null;
+        if (v) { f.hidden = false; f.dataset.embed = v.embed; f.dataset.orig = v.orig; f.dataset.title = v.title; }
+        else f.hidden = true;
+      }

